// Помощники #37cdff: пометка ребёнка «לבקש בדיקה» и её вид у родителя («המלצות אחרונות», «למה זה הומלץ»).
// Expo-роутер держит скрытые экраны в DOM — считаем только видимые элементы.
// Селекторы с пометкой TODO verify selector взяты из кейсов/брифа (.qa/research/37cdff.md), в браузере при записи не проверялись.
import { Page, expect } from '@playwright/test';

/** Постоянный ребёнок с готовыми рекомендациями (чтение 5/10, письмо 2/4). НЕ удалять (context.md). */
export const CHILD = 'QA-R2-1';
export const CHILD_ID = 'b9ef1552-4cc7-4d72-a9c3-d02d66d19af1';

export const T = {
  childWhy: /למה זה הומלץ/,
  childAsk: 'לבקש בדיקה',
  childAsked: /ההורה יראה את הבקשה/,
  parentInsights: 'תובנות והמלצות',
  parentRecent: 'המלצות אחרונות',
  markChild: 'הילד ביקש לבדוק',
  markReview: 'בבדיקה',
  openReview: 'פתיחת בקשת בדיקה',
  sendReview: 'שליחת בקשה',
  otherReason: 'אחר',
};

/** Открыть «תובנות והמלצות» → «המלצות אחרונות» ребёнка у родителя. */
export async function openParentRecent(page: Page, childId = CHILD_ID) {
  await page.goto(`/children/${childId}`);
  await page.getByRole('button', { name: T.parentInsights }).or(page.getByRole('link', { name: T.parentInsights })).filter({ visible: true }).first().click(); // TODO verify selector
  await expect(page.getByText(T.parentRecent).filter({ visible: true }).first()).toBeVisible();
}

/** Видимые метки в списке рекомендаций. «בבדיקה» — отдельным словом (не часть «בקשת בדיקה»). */
export function parentMarks(page: Page) {
  return {
    child: page.getByText(T.markChild, { exact: true }).filter({ visible: true }),
    review: page.getByText(new RegExp(`(^|[•·]\\s*)${T.markReview}(\\s*[•·]|$)`)).filter({ visible: true }),
  };
}

/** Строки «המלצות אחרונות» (нажимаются и ведут на «למה זה הומלץ»). TODO verify selector: роль строки (button / link). */
export function recentRows(page: Page) {
  return page.getByRole('button').or(page.getByRole('link')).filter({ visible: true });
}
